import java.math.BigInteger;
import java.util.Scanner;

public class Main {

    private static int weight;
    private static int itemMass;
    private static boolean[] used = new boolean[100];

    public boolean isBalanced() {
        return balance(itemMass, 0L);
    }

    private boolean balance(long left, long right) {
        if (left == right) {
            return true;
        }

        if (left > right) {
            long piece = getMass(left - right);
            if (piece == 0) {
                return false;
            }
            return balance(left, right + piece);
        } else {
            long piece = getMass(right - left);
            if (piece == 0) {
                return false;
            }
            return balance(left + piece, right);
        }
    }

    public long getMass(long mass) {
        int logBase = (int) (Math.log(mass) / Math.log(weight));

        BigInteger bi = new BigInteger(Integer.toString(weight));
        bi = bi.pow(logBase + 1);
        bi = bi.subtract(BigInteger.ONE);
        bi = bi.divide(new BigInteger(Integer.toString(weight - 1)));
        long sumTotal = bi.longValue();

        long result;
        if (mass > sumTotal && !used[logBase + 1]) {
            result = (int) Math.pow(weight, logBase + 1);
            used[logBase + 1] = true;
        } else if (mass <= sumTotal && !used[logBase]) {
            result = (int) Math.pow(weight, logBase);
            used[logBase] = true;
        } else {
            result = 0;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Main.weight = sc.nextInt();
        Main.itemMass = sc.nextInt();
        Main wb = new Main();
        System.out.println(wb.isBalanced() ? "YES" : "NO");
    }
}
